param([string]$BackendRoot = $PSScriptRoot)
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest
function Fail([string]$Message){Write-Host "";Write-Host "ABORTED: $Message" -ForegroundColor Red;throw $Message}
function Sha([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Decode([string]$Base64){[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64))}
function WriteUtf8([string]$Path,[string]$Content){$e=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText($Path,$Content,$e)}
function Rel([string]$Root,[string]$Path){$prefix=$Root.TrimEnd('\')+'\';if($Path.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){return $Path.Substring($prefix.Length)};return $Path}
$BackendRoot=(Resolve-Path -LiteralPath $BackendRoot).Path; Set-Location $BackendRoot
Write-Host "Manna Backend - Vendor Sequential Onboarding + Optional Precise Location V4" -ForegroundColor Green
Write-Host "Makes pickup GPS optional for initial onboarding, adds accuracy/capturedAt, and enforces backend step order."
Write-Host "Creates a Prisma migration artifact but DOES NOT execute it against any database."
foreach($i in @('package.json','src')){if(-not(Test-Path -LiteralPath (Join-Path $BackendRoot $i))){Fail "Run from Manna backend root or pass -BackendRoot. Missing: $i"}}
$targets=@(
 @{Rel='src\lib\vendors\vendorOnboardingService.ts';Before='284a270c7582760bf069fc7a361258647d6f38e4d45226633fe415d547941fc2';After='82b0cfec0c6e2fe03d87d08d55e1e067706aa4a6c122fbfd41a52bcc51d0d007';Data=''},
 @{Rel='src\lib\marketplace\vendorOrders.ts';Before='43eb26dbb9b9314ccea3f970969fd9d6191d77eea288c7b1665ebb0c31e0fa83';After='63ee0e7300b67855c344d89eebbd13a15178b078f3bee1d4fce05b38d4ba8559';Data=''},
 @{Rel='src\app\api\vendors\onboarding\status\route.ts';Before='ecca7814b6afad27dfab2288df61ed90131efabee5ef0c41bb54bbf7e35b0c5e';After='2f8b64c2c85ba9b598763ca9d315178918af91d35c27b48a1aee355906017a55';Data=''}
)
$newRel='src\app\api\vendors\onboarding\market-clusters\route.ts';$newAfter='17aa5dece6b6eb142e314cf7ed04f7042c4acc763e8ccfbbd0e80202eb716e5f';$newData=''
Write-Host "`n==> Re-proving backend source boundary" -ForegroundColor Cyan
$changed=@();foreach($t in $targets){$p=Join-Path $BackendRoot $t.Rel;if(-not(Test-Path -LiteralPath $p)){Fail "Missing $($t.Rel)"};$h=Sha $p;if($h -ne $t.Before -and $h -ne $t.After){Fail "Unexpected drift in $($t.Rel): $h"};if($h -ne $t.After){$changed+=$t};Write-Host "  VERIFIED   $($t.Rel)"}
$newPath=Join-Path $BackendRoot $newRel
if(Test-Path -LiteralPath $newPath){if((Sha $newPath)-ne $newAfter){Fail "Unexpected existing $newRel"}}else{$changed+=@{Rel=$newRel;After=$newAfter;Data=$newData;New=$true}}
Write-Host "  VERIFIED   $newRel"
$schemaCandidates=@((Join-Path $BackendRoot 'prisma\schema.prisma'),(Join-Path $BackendRoot 'schema.prisma'))|Where-Object{Test-Path -LiteralPath $_}
if($schemaCandidates.Count -ne 1){Fail "Expected exactly one Prisma schema at prisma/schema.prisma or schema.prisma."}
$schemaPath=$schemaCandidates[0];$schemaRaw=Get-Content -LiteralPath $schemaPath -Raw
$match=[regex]::Match($schemaRaw,'(?ms)^model\s+VendorPickupLocation\s*\{.*?^\}')
if(-not $match.Success){Fail 'VendorPickupLocation model not found in Prisma schema.'}
$block=$match.Value;$schemaNeedsWrite=$false
if($block -match '(?m)^\s*latitude\s+Float\s'){$schemaNeedsWrite=$true}elseif($block -notmatch '(?m)^\s*latitude\s+Float\?'){Fail 'Unexpected VendorPickupLocation.latitude type; expected Float or Float?.'}
if($block -match '(?m)^\s*longitude\s+Float\s'){$schemaNeedsWrite=$true}elseif($block -notmatch '(?m)^\s*longitude\s+Float\?'){Fail 'Unexpected VendorPickupLocation.longitude type; expected Float or Float?.'}
if($block -notmatch '(?m)^\s*accuracy\s+Float\?'){$schemaNeedsWrite=$true}
if($block -notmatch '(?m)^\s*capturedAt\s+DateTime\?'){$schemaNeedsWrite=$true}
Write-Host "  VERIFIED   $((Rel $BackendRoot $schemaPath))"
$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$backup=Join-Path $BackendRoot ".manna-backups\vendor-sequential-location-v4-$stamp"
if($changed.Count -gt 0 -or $schemaNeedsWrite){Write-Host "`n==> Creating guarded backup" -ForegroundColor Cyan;foreach($t in $targets){$src=Join-Path $BackendRoot $t.Rel;$dst=Join-Path $backup $t.Rel;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dst)|Out-Null;Copy-Item -LiteralPath $src -Destination $dst -Force};$sdst=Join-Path $backup (Rel $BackendRoot $schemaPath);New-Item -ItemType Directory -Force -Path (Split-Path -Parent $sdst)|Out-Null;Copy-Item -LiteralPath $schemaPath -Destination $sdst -Force;Write-Host "  backup: $backup"}
if($changed.Count -gt 0){Write-Host "`n==> Applying backend source corrections" -ForegroundColor Cyan;foreach($t in $changed){$p=Join-Path $BackendRoot $t.Rel;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $p)|Out-Null;WriteUtf8 $p (Decode $t.Data);Write-Host "  PATCHED    $($t.Rel)"}}
if($schemaNeedsWrite){Write-Host "`n==> Updating Prisma schema (source only)" -ForegroundColor Cyan;$newBlock=$block;$newBlock=[regex]::Replace($newBlock,'(?m)^(\s*latitude\s+Float)(?!\?)(.*)$','$1?$2');$newBlock=[regex]::Replace($newBlock,'(?m)^(\s*longitude\s+Float)(?!\?)(.*)$','$1?$2');if($newBlock -notmatch '(?m)^\s*accuracy\s+Float\?'){$newBlock=[regex]::Replace($newBlock,'(?m)^(\s*longitude\s+Float\?.*)$',"`$1`r`n  accuracy Float?",1)};if($newBlock -notmatch '(?m)^\s*capturedAt\s+DateTime\?'){$newBlock=[regex]::Replace($newBlock,'(?m)^(\s*accuracy\s+Float\?.*)$',"`$1`r`n  capturedAt DateTime?",1)};$schemaRaw=$schemaRaw.Substring(0,$match.Index)+$newBlock+$schemaRaw.Substring($match.Index+$match.Length);WriteUtf8 $schemaPath $schemaRaw;Write-Host '  latitude/longitude nullable + accuracy/capturedAt: PATCHED'}
$schemaNow=Get-Content -LiteralPath $schemaPath -Raw;$m=[regex]::Match($schemaNow,'(?ms)^model\s+VendorPickupLocation\s*\{.*?^\}');$b=$m.Value
$table='VendorPickupLocation';$tm=[regex]::Match($b,'@@map\("([^"]+)"\)');if($tm.Success){$table=$tm.Groups[1].Value}
function FieldCol([string]$Block,[string]$Field){$rx='(?m)^\s*'+[regex]::Escape($Field)+'\s+\S+.*?@map\("([^"]+)"\)';$fm=[regex]::Match($Block,$rx);if($fm.Success){return $fm.Groups[1].Value};return $Field}
$latCol=FieldCol $b 'latitude';$lngCol=FieldCol $b 'longitude';$accCol=FieldCol $b 'accuracy';$capCol=FieldCol $b 'capturedAt'
$migrationsRoot=Join-Path (Split-Path -Parent $schemaPath) 'migrations';New-Item -ItemType Directory -Force -Path $migrationsRoot|Out-Null
$marker='MANNA_VENDOR_PICKUP_OPTIONAL_PRECISE_LOCATION_V1';$existingMigration=Get-ChildItem -LiteralPath $migrationsRoot -Filter migration.sql -File -Recurse -ErrorAction SilentlyContinue|Where-Object{Select-String -LiteralPath $_.FullName -Pattern $marker -SimpleMatch -Quiet}|Select-Object -First 1
if(-not $existingMigration){$migDir=Join-Path $migrationsRoot ((Get-Date -Format 'yyyyMMddHHmmss')+'_vendor_pickup_optional_precise_location');New-Item -ItemType Directory -Force -Path $migDir|Out-Null;$mig=Join-Path $migDir 'migration.sql';$sql=@"
-- $marker
-- Location is optional during vendor onboarding; precise coordinates become a later readiness requirement.
ALTER TABLE "$table" ALTER COLUMN "$latCol" DROP NOT NULL;
ALTER TABLE "$table" ALTER COLUMN "$lngCol" DROP NOT NULL;
ALTER TABLE "$table" ADD COLUMN IF NOT EXISTS "$accCol" DOUBLE PRECISION;
ALTER TABLE "$table" ADD COLUMN IF NOT EXISTS "$capCol" TIMESTAMP(3);
"@;WriteUtf8 $mig $sql;Write-Host "  migration artifact: $((Rel $BackendRoot $mig))"}else{Write-Host "  migration artifact already present: $((Rel $BackendRoot $existingMigration.FullName))"}
Write-Host "`n==> Verifying backend invariants" -ForegroundColor Cyan
foreach($t in $targets){if((Sha (Join-Path $BackendRoot $t.Rel))-ne $t.After){Fail "Post-write hash mismatch: $($t.Rel)"}}
if((Sha $newPath)-ne $newAfter){Fail "Post-write hash mismatch: $newRel"}
$svc=Get-Content -LiteralPath (Join-Path $BackendRoot 'src\lib\vendors\vendorOnboardingService.ts') -Raw
if($svc -notmatch 'nextRequiredStep' -or $svc -notmatch 'assertBankComplete' -or $svc -notmatch 'requiredStepsComplete' -or $svc -notmatch 'must be submitted for Manna review before approval'){Fail 'Sequential backend guards missing.'}
if($svc -match 'missingSteps\.push\("PICKUP_LOCATION"\)'){Fail 'Pickup location is still an onboarding requirement.'}
$schemaCheck=Get-Content -LiteralPath $schemaPath -Raw
if($schemaCheck -notmatch '(?m)^\s*latitude\s+Float\?' -or $schemaCheck -notmatch '(?m)^\s*longitude\s+Float\?' -or $schemaCheck -notmatch '(?m)^\s*accuracy\s+Float\?' -or $schemaCheck -notmatch '(?m)^\s*capturedAt\s+DateTime\?'){Fail 'Prisma location fields not in expected optional form.'}
Write-Host '  strict sequential onboarding: VERIFIED';Write-Host '  pickup location removed from required onboarding: VERIFIED';Write-Host '  approved vendor visibility gated by precise location: VERIFIED';Write-Host '  delivery order creation rejects missing precise pickup coordinates: VERIFIED';Write-Host '  schema migration artifact: CREATED/PRESERVED';Write-Host '  database mutation: NOT EXECUTED'
$prismaCmd=Join-Path $BackendRoot 'node_modules\.bin\prisma.cmd'
if(Test-Path -LiteralPath $prismaCmd){Write-Host "`n==> Regenerating Prisma client" -ForegroundColor Cyan;& $prismaCmd generate --schema $schemaPath;if($LASTEXITCODE -ne 0){Fail "prisma generate failed: $LASTEXITCODE"};Write-Host '  prisma generate: GREEN' -ForegroundColor Green}else{Write-Host "`nNOTE: node_modules Prisma CLI not present; prisma generate/build validation deferred until dependencies are installed." -ForegroundColor Yellow}
if(Test-Path -LiteralPath (Join-Path $BackendRoot 'node_modules')){$pkg=Get-Content -LiteralPath (Join-Path $BackendRoot 'package.json') -Raw|ConvertFrom-Json;if($pkg.scripts.build){Write-Host "`n==> Running backend build" -ForegroundColor Cyan;& npm.cmd run build;if($LASTEXITCODE -ne 0){Fail "backend build failed: $LASTEXITCODE"};Write-Host '  build: GREEN' -ForegroundColor Green}}
Write-Host "`nManna backend vendor onboarding V4 source is GREEN." -ForegroundColor Green
Write-Host 'IMPORTANT: the generated Prisma migration has NOT been applied to any database yet.' -ForegroundColor Yellow
Write-Host 'Apply the migration to Development before live end-to-end testing.' -ForegroundColor Yellow
if($changed.Count -gt 0 -or $schemaNeedsWrite){Write-Host "Backup retained at: $backup"}